module pipe_domain {
 // Peer-domain ownership only. Existing root/GC models retain their duties.
 type State={holders:Set[int],queue:List[int],sent:int,received:int,closed:bool,waiting:bool,woken:bool,stopped:bool}
 pure val initial:State={holders:Set(),queue:[],sent:0,received:0,closed:false,waiting:false,woken:false,stopped:false}
 var s:State
 action init=s'=initial
 val conservation=s.sent-s.received==s.queue.length()
 val bounded=s.received>=0 and s.received<=s.sent and s.sent<=3
 val uniqueOwner=s.holders.size()<=1 and s.holders.subseteq(Set(0,1))
 val waitReleased=not(s.waiting and s.holders.contains(1))
 val closedWake=not(s.closed and s.waiting) or s.woken
 val safe=all{conservation,bounded,uniqueOwner,waitReleased,closedWake}
 action lock(e:int):bool=all{s.holders.size()==0,not(s.stopped),e>=0,e<=1,not(e==1 and s.waiting),s'={...s,holders:Set(e)}}
 action unlock(e:int):bool=all{s.holders.contains(e),s'={...s,holders:s.holders.exclude(Set(e))}}
 action write=all{s.holders.contains(0),not(s.closed),s.sent<3,s'={...s,queue:s.queue.append(s.sent),sent:s.sent+1,woken:s.woken or s.waiting}}
 action read=all{s.holders.contains(1),s.queue.length()>0,s'={...s,queue:s.queue.tail(),received:s.received+1}}
 action wait=all{s.holders.contains(1),s.queue.length()==0,not(s.closed),s'={...s,holders:s.holders.exclude(Set(1)),waiting:true,woken:false}}
 action reacquire=all{s.holders.size()==0,s.waiting,s.woken,s'={...s,holders:Set(1),waiting:false,woken:false}}
 action close=all{s.holders.contains(0),not(s.closed),s'={...s,closed:true,woken:s.woken or s.waiting}}
 action exceptionalReturn(e:int):bool=unlock(e)
 action exceptionInWaitHook=all{s.holders.size()==0,s.waiting,s'={...s,waiting:false,woken:false}}
 action finish=all{s.holders.size()==0,s.closed,s.queue.length()==0,not(s.waiting),s'={...s,stopped:true}}
 action step=any{lock(0),lock(1),unlock(0),unlock(1),write,read,wait,reacquire,close,exceptionalReturn(0),exceptionalReturn(1),exceptionInWaitHook,finish,all{s.stopped,s'=s}}
 run deliveryTest=init.then(lock(1)).then(wait).then(lock(0)).then(write).then(unlock(0)).then(reacquire).then(read).then(unlock(1)).then(all{assert(safe and s.received==1),s'=s})
 run closedWakeTest=init.then(lock(1)).then(wait).then(lock(0)).then(close).then(unlock(0)).then(reacquire).then(unlock(1)).then(finish).then(all{assert(safe and s.stopped),s'=s})
 run hookFailureTest=init.then(lock(1)).then(wait).then(exceptionInWaitHook).then(lock(0)).then(write).then(unlock(0)).then(lock(1)).then(read).then(unlock(1)).then(all{assert(safe),s'=s})
 // Old per-endpoint locks admit both holders, despite shared FIFO/cursors.
 action splitLock(e:int):bool=all{e>=0,e<=1,not(s.holders.contains(e)),s'={...s,holders:s.holders.union(Set(e))}}
 run splitOwnerNegativeTest=init.then(splitLock(0)).then(splitLock(1)).then(all{assert(not(uniqueOwner)),s'=s})
 run lostWakeNegativeTest=init.then(lock(1)).then(wait).then(lock(0)).then(s'={...s,closed:true}).then(all{assert(not(closedWake)),s'=s})
 run waitHoldingOwnerNegativeTest=init.then(lock(1)).then(s'={...s,waiting:true}).then(all{assert(not(waitReleased)),s'=s})
 run duplicateReadNegativeTest=init.then(lock(0)).then(write).then(unlock(0)).then(lock(1)).then(read).then(s'={...s,received:s.received+1}).then(all{assert(not(conservation)),s'=s})
}
